import{_ as r,o as s,c as a,a0 as o}from"./chunks/framework.BL79I5mR.js";const t="/docs/assets/users-and-groups.DGUR461B.png",n="/docs/assets/users-groups.Crc720kN.png",i="/docs/assets/create-new-group.tdh0o09y.png",g="/docs/assets/groups-add-subgroup.bKkQH8gU.png",p="/docs/assets/groups-subgroup-indicators.JSDUyP1E.png",m="/docs/assets/user-group-details.B5HWK0hy.png",u="/docs/assets/groups-edit-details.dqAO6R33.png",c="/docs/assets/managers.CVo28BXK.png",d="/docs/assets/add-members.CcEtvw9V.png",h="/docs/assets/available-managers.ECo4nY_t.png",l="/docs/assets/remove-managers.Y2-_b2ds.png",b="/docs/assets/reassign-as-member.Dh8f7bwv.png",_="/docs/assets/members.mu2_ZoW9.png",f="/docs/assets/add-members.CcEtvw9V.png",v="/docs/assets/available-members.DYUMDGD4.png",M="/docs/assets/remove.CHGlm20i.png",k="/docs/assets/reassign-as-manager.D2vXMzTW.png",w="/docs/assets/save-user-group.CA2XO9tv.png",S=JSON.parse('{"title":"User Group Management","description":"","frontmatter":{},"headers":[],"relativePath":"authoring/users-and-groups/index.md","filePath":"authoring/users-and-groups/README.md"}'),G={name:"authoring/users-and-groups/index.md"};function y(q,e,T,x,A,C){return s(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="user-group-management" tabindex="-1">User Group Management <a class="header-anchor" href="#user-group-management" aria-label="Permalink to &quot;User Group Management&quot;">​</a></h1><p>In the CaSS authoring environment, user groups allow for multiple users to assume a single shared &#39;identity&#39;. Members of a group are granted access to any CaSS object that the group has been explicitly assigned.</p><p>Subgroups can be created within Groups to further organize and define access to CaSS objects for multiple users.</p><h2 id="accessing-the-cat-user-group-manager" tabindex="-1">Accessing the CAT User Group Manager <a class="header-anchor" href="#accessing-the-cat-user-group-manager" aria-label="Permalink to &quot;Accessing the CAT User Group Manager&quot;">​</a></h2><p><strong>Important: To access the CAT user group manager, you must be logged into the CAT application.</strong></p><p>The CAT user group manager can be accessed at any time by selecting the <em><strong>users and groups</strong></em> icon on the lower left corner of the navigation menu.</p><p><img src="'+t+'" alt="Users and groups"></p><p><strong>CAT User Group Manager - Navigation Menu - Users and Groups</strong></p><p>The <em><strong>My User Groups</strong></em> list contains options for creating a new group, viewing group members, and accessing existing groups.</p><p><img src="'+n+'" alt="Users groups"></p><p>To view a list of all group members, click on <em><strong>Member List</strong></em> under <em><strong>My User Groups</strong></em>. This only lists users who are already within a group.</p><h2 id="creating-a-new-user-group" tabindex="-1">Creating a New User Group <a class="header-anchor" href="#creating-a-new-user-group" aria-label="Permalink to &quot;Creating a New User Group&quot;">​</a></h2><p>To create a new group, click on the <em><strong>create new group</strong></em> button under <em><strong>My User Groups</strong></em>.</p><p><img src="'+i+'" alt="Create new group"></p><p>A new group is created with a default name and description.</p><div class="tip custom-block"><p class="custom-block-title">Note</p><p>There may be noticeable processing time when creating a new group. CAT user groups are assigned identity keys that must be generated at creation time. This process may take several seconds.</p></div><h2 id="creating-a-new-sub-group" tabindex="-1">Creating a New Sub-Group <a class="header-anchor" href="#creating-a-new-sub-group" aria-label="Permalink to &quot;Creating a New Sub-Group&quot;">​</a></h2><p>To add a sub-group to a currently open group, click on the <em><strong>add sub-group</strong></em> button under <em><strong>Group actions</strong></em>. <em>Sub-groups</em> can be created within <em>Groups</em> to further organize and define access to CaSS objects for multiple users.</p><p><img src="'+g+'" alt="Create new sub-group"></p><p>A new sub-group is created with a default name and description. The path of the group and the listing under <em><strong>My User Groups</strong></em> indicate the parent of the sub-group.</p><p><img src="'+p+'" alt="Sub-group Indicators"></p><p>The actions for managing users and editing groups apply to sub-groups as well.</p><h2 id="managing-a-user-group" tabindex="-1">Managing a User Group <a class="header-anchor" href="#managing-a-user-group" aria-label="Permalink to &quot;Managing a User Group&quot;">​</a></h2><p>To access existing groups in the current CAT instance, click on the group name under <em><strong>My User Groups</strong></em> to the left of the <em><strong>Group Details</strong></em>.</p><p><em>Group Details</em> show the name, description, and a list of members within the group.</p><p><img src="'+m+'" alt="User Group Details"></p><p>Click on the edit icon next to the <em><strong>name</strong></em> and <em><strong>description</strong></em> to edit either of these properties. When you are done editing, click &quot;done editing&quot; to save changes.</p><p><img src="'+u+'" alt="Edit Group Details"></p><h3 id="group-managers" tabindex="-1">Group Managers <a class="header-anchor" href="#group-managers" aria-label="Permalink to &quot;Group Managers&quot;">​</a></h3><p>Group managers can add and remove members and other managers to the group. Managers also share the owner and reader privileges assigned to the group.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>You cannot remove yourself as a manager from the current group</p></div><p><img src="'+c+'" alt="Managers"></p><h4 id="add-managers" tabindex="-1">Add Managers <a class="header-anchor" href="#add-managers" aria-label="Permalink to &quot;Add Managers&quot;">​</a></h4><p>To add managers to a group, click on the <em><strong>+ member</strong></em> button under <em><strong>Group actions</strong></em> in the top right corner.</p><p><img src="'+d+'" alt="Available Managers"></p><p>In the <em><strong>Add members</strong></em> dialogue, select the desired permissions next to the name of the member or members you would like to add to the group. The member icon with a shield, as shown above the check box outlined in red below, represents a manager for this group. When you are finished selecting member permissions click &quot;apply&quot;.</p><p><img src="'+h+'" alt="Available Managers"></p><h4 id="remove-managers" tabindex="-1">Remove Managers <a class="header-anchor" href="#remove-managers" aria-label="Permalink to &quot;Remove Managers&quot;">​</a></h4><p>Group managers can be removed from the group by clicking on the <em><strong>remove icon</strong></em>.</p><p><img src="'+l+'" alt="Remove Managers"></p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>You cannot remove yourself as a manager from the current group</p></div><h4 id="reassign-manager" tabindex="-1">Reassign Manager <a class="header-anchor" href="#reassign-manager" aria-label="Permalink to &quot;Reassign Manager&quot;">​</a></h4><p>Managers can be reassigned as a group member by clicking the <em><strong>change role</strong></em> button.</p><p>When a role is changed from manager to member, the list is re-sorted to place the member beneath existing managers in the list.</p><p><img src="'+b+'" alt="Reassign as member"></p><h3 id="group-members" tabindex="-1">Group Members <a class="header-anchor" href="#group-members" aria-label="Permalink to &quot;Group Members&quot;">​</a></h3><p>Group members share the owner and reader privileges assigned to the group.</p><p><img src="'+_+'" alt="Members"></p><h4 id="add-members" tabindex="-1">Add Members <a class="header-anchor" href="#add-members" aria-label="Permalink to &quot;Add Members&quot;">​</a></h4><p>To add members to a group, click on the <em><strong>+ member</strong></em> button under <em><strong>Group actions</strong></em> in the top right corner.</p><p><img src="'+f+'" alt="Available Managers"></p><p>In the <em><strong>Add members</strong></em> dialogue, select the desired permissions next to the name of the member or members you would like to add to the group. The <em>member icon without a shield</em>, as shown above the check box outlined in red below, represents a member for this group. When you are finished selecting member permissions click <em><strong>apply</strong></em>.</p><p><img src="'+v+'" alt="Available Managers"></p><h4 id="remove-members" tabindex="-1">Remove Members <a class="header-anchor" href="#remove-members" aria-label="Permalink to &quot;Remove Members&quot;">​</a></h4><p>Group members can be removed from the group by clicking on the remove icon.</p><p><img src="'+M+'" alt="Remove Members"></p><h4 id="reassign-member" tabindex="-1">Reassign Member <a class="header-anchor" href="#reassign-member" aria-label="Permalink to &quot;Reassign Member&quot;">​</a></h4><p>Members can be reassigned as a group manager by clicking <em><strong>change role</strong></em> button.</p><p>When a role is changed from member to manager, the list is re-sorted to place the new manager above existing members in the list.</p><p><img src="'+k+'" alt="Reassign as manager"></p><h3 id="saving-the-group" tabindex="-1">Saving the Group <a class="header-anchor" href="#saving-the-group" aria-label="Permalink to &quot;Saving the Group&quot;">​</a></h3><p>Changes to Groups can be saved by clicking on the save button under <em><strong>Group actions</strong></em> in the top right corner.</p><p><img src="'+w+'" alt="Save User Group"></p>',63)])])}const P=r(G,[["render",y]]);export{S as __pageData,P as default};
